linked_redis_caches.tfType:
map(object({
    linked_redis_cache_resource_id = string
    linked_redis_cache_location    = string
    server_role                    = string
  }))

managed_identities.tfType:
object({
    system_assigned            = optional(bool, false)
    user_assigned_resource_ids = optional(set(string), [])
  })

cache_firewall_rules.tfType:
map(object({
    name     = string
    start_ip = string
    end_ip   = string
  }))

lock.tfType:
object({
    kind = string
    name = optional(string, null)
  })

patch_schedule.tfType:
set(object({
    day_of_week        = optional(string, "Saturday")
    maintenance_window = optional(string, "PT5H")
    start_hour_utc     = optional(number, 0)
  }))

cache_access_policy_assignments.tfType:
map(object({
    name               = string
    access_policy_name = string
    object_id          = string
    object_id_alias    = string
  }))
